<?php
/**
 * SpeX-Trading App Database Configuration Save
 * @package SpeX-Trading V3.5
 * @author SpeXD
 * @instagram spexd
*/

header('Content-Type: application/json');

if (session_status() === PHP_SESSION_NONE) {
    session_start();
}

if (!isset($_SESSION['install_config'])) {
    echo json_encode([
        'success' => false,
        'message' => 'No database configuration found. Please test the connection first.'
    ]);
    exit;
}

$config = $_SESSION['install_config'];

$configContent = '<?php 
/**
 * SpeX-Trading App Database Configuration
 * Auto-generated on ' . date('Y-m-d H:i:s') . '
 * DO NOT EDIT THIS FILE MANUALLY
*/

$RootHost = \'' . addslashes($config['host']) . '\';
$RootUser = \'' . addslashes($config['username']) . '\';
$RootPass = \'' . addslashes($config['password']) . '\';
$RootName = \'' . addslashes($config['database']) . '\';

$DataBaseBakcupDay = ' . intval($config['backup_days']) . ';

if (basename(__FILE__) == basename($_SERVER[\'SCRIPT_FILENAME\'])) {
    include __DIR__ . \'/web.html\';
    exit();
}
?>';

try {
    $configPath = '../../core/system/config.php';
    $configDir = dirname($configPath);
    
    if (!is_dir($configDir)) {
        if (!mkdir($configDir, 0755, true)) {
            throw new Exception('Could not create config directory: ' . $configDir);
        }
    }
    
    if (!is_writable($configDir)) {
        throw new Exception('Config directory is not writable: ' . $configDir);
    }
    
    if (file_exists($configPath)) {
        if (!is_writable($configPath)) {
            if (!chmod($configPath, 0644)) {
                throw new Exception('Cannot change permissions of existing config file');
            }
        }
        
        if (!unlink($configPath)) {
            throw new Exception('Cannot delete existing config file: ' . $configPath);
        }
    }
    
    if (file_put_contents($configPath, $configContent, LOCK_EX) === false) {
        throw new Exception('Could not write configuration file to: ' . $configPath);
    }
    
    if (!chmod($configPath, 0644)) {
        throw new Exception('Could not set permissions on config file');
    }
    
    if (!is_readable($configPath)) {
        throw new Exception('Configuration file is not readable after creation');
    }
    
    $testContent = file_get_contents($configPath);
    if (empty($testContent) || strpos($testContent, '$RootHost') === false) {
        throw new Exception('Configuration file was not written correctly');
    }
    
    try {
        $stepsFile = __DIR__ . '/../step.xml';
        if (file_exists($stepsFile)) {
            $xml = simplexml_load_file($stepsFile);
            if ($xml !== false) {
                foreach ($xml->steps->step as $step) {
                    if ((string)$step['name'] === 'DB_CONNECT') {
                        $step['value'] = '1';
                        break;
                    }
                }
                $xml->asXML($stepsFile);
            }
        }
    } catch (Exception $e) {
        error_log('Could not update installation step: ' . $e->getMessage());
    }
    
    echo json_encode([
        'success' => true,
        'message' => 'Database configuration saved successfully',
        'details' => [
            'config_path' => $configPath,
            'file_size' => filesize($configPath) . ' bytes',
            'permissions' => substr(sprintf('%o', fileperms($configPath)), -4),
            'writable' => is_writable($configPath) ? 'Yes' : 'No',
            'readable' => is_readable($configPath) ? 'Yes' : 'No'
        ]
    ]);
    
} catch (Exception $e) {
    echo json_encode([
        'success' => false,
        'message' => 'Failed to save configuration: ' . $e->getMessage()
    ]);
}
?>